class Component extends DCLogic {
 constructor(p){super(p);this.state={people:[{id:'timur',name:'Тимур Ахмедов',ini:'ТА',color:'av-b',status:'Актуальность не проверена',context:'Раньше помогал с перевозкой материалов.',availability:'',note:''},{id:'vera',name:'Вера Новикова',ini:'ВН',color:'av-o',status:'Актуальность не проверена',context:'Помогала с фотографиями мероприятий.',availability:'',note:''},{id:'ksenia',name:'Ксения Рябова',ini:'КР',color:'av-v',status:'Сейчас на паузе',context:'Договорились вернуться к обсуждению участия в декабре.',availability:'После декабря',note:''}],query:'',filter:'Актуальность не проверена',sel:'',result:'Актуальность не проверена',availability:'',note:'',saved:false,error:''};}
 open(p){try{if(typeof scrollTo==='function')scrollTo(0,0);}catch(_){}this.setState({sel:p.id,result:p.status,availability:p.availability,note:p.note,saved:false,error:''});}
 renderVals(){const s=this.state,person=s.people.find(p=>p.id===s.sel)||s.people[0];const filtered=s.people.filter(p=>(s.filter==='all'||p.status===s.filter)&&p.name.toLowerCase().includes(s.query.toLowerCase()));const change=k=>e=>this.setState({[k]:e.target.value,saved:false,error:''});return {query:s.query,search:change('query'),filters:[['Актуальность не проверена','Проверить'],['Ждём ответа','Ждём ответа'],['all','Все']].map(([id,title])=>({title,cls:'chip'+(id===s.filter?' is-on':''),pick:()=>this.setState({filter:id})})),people:filtered.map(p=>({...p,avatar:'avatar '+p.color,pick:()=>this.open(p)})),empty:!filtered.length,listTitle:'Проверить по одному',openNext:()=>{const p=s.people.find(p=>p.status==='Актуальность не проверена');if(p)this.open(p);else this.setState({filter:'all',sel:'',query:''});},reset:()=>this.setState({filter:'all',query:''}),hasSelected:!!s.sel,person,result:s.result,availability:s.availability,note:s.note,changeResult:change('result'),changeAvailability:change('availability'),changeNote:change('note'),close:()=>this.setState({sel:''}),save:()=>{if(s.result==='Готов помогать'&&!s.availability.trim()){this.setState({error:'Уточните доступность, прежде чем добавлять человека в резерв.'});return;}this.setState({people:s.people.map(p=>p.id===s.sel?{...p,status:s.result,availability:s.availability,note:s.note}:p),sel:'',saved:true,error:''});},dialogKey:e=>{if(e.key==='Escape')this.setState({sel:'',error:''});if(e.key==='Tab'){const items=Array.from(e.currentTarget.querySelectorAll('button,input,textarea')).filter(x=>x.getClientRects().length);if(e.shiftKey&&e.target===items[0]){e.preventDefault();items[items.length-1].focus();}else if(!e.shiftKey&&e.target===items[items.length-1]){e.preventDefault();items[0].focus();}}},saved:s.saved,hasError:!!s.error,error:s.error};}
}
